G.assetRoot="HussValley/ui/giorgio/"
local function mediaPath(path)
 local own=G.assetRoot..path
 local ok,present=pcall(isfile,own)
 if ok and present then return own end
 return "Giorgio/assets/"..path
end
local function installedMedia(spec)
 local path=spec and mediaPath(spec.folder.."/"..spec.prefix..string.format("%0"..spec.digits.."d",spec.first).."."..spec.ext)
 local ok,present=pcall(isfile,path)
 return ok and present and spec or nil
end
