function UI:Destroy()
 if self._destroyed then return end
 self._destroyed=true
 local callback=owner and owner.onDestroy
 if L.live() then getgenv().__HUSS_LUMEN_GEN+=1 end
 L.teardown()
 if shared.__V18UI==self then shared.__V18UI=nil end
 if callback then L.try("huss.destroy",callback) end
 table.clear(self.Flags)
end
return UI

 end)()
end

local CONFIG_FOLDER = "HussValley/configs"
local AUTOLOAD_FILE = "HussValley/autoload.txt"

local function notify(title, text)
	if uiWindow then uiWindow:Notify({ Title = title, Text = text, Duration = 4 }) end
end

-- Applies a config the Settings tab saved (HussValley/configs/<name>.json); used by "load on start".
---@param name string
---@param quiet boolean?
local function loadConfig(name, quiet)
	local path = CONFIG_FOLDER .. "/" .. name .. ".json"
	local success, data = pcall(function()
		if not isfile(path) then return nil end

		return game:GetService("HttpService"):JSONDecode(readfile(path))
	end)

	if not success or type(data) ~= "table" then
		if not quiet then notify("No config", name .. " has nothing saved yet") end
		return
	end

	local applied = 0
	for flagName, value in data do
		local entry = ui.Flags[flagName]
		if entry and string.sub(flagName, 1, 4) ~= "cfg_" and pcall(entry.Set, value) then applied += 1 end
	end

	if not quiet then notify("Config loaded", string.format("%s (%d settings)", name, applied)) end
end

---@param role string?
---@return string, number, string
local function roleCard()
	local role = localPlayer:GetAttribute("GameRole")
	local runState = localPlayer:GetAttribute("RunState")
	local alpha = (role == "Runner" or role == "Catcher") and runState == "Active" and 1 or 0.12
	return tostring(role or "?"), alpha, tostring(runState or "")
end

-- Teleport ------------------------------------------------------------------------------------------------------------
-- The field has two invisible safe-zone boxes (SafezoneASide / SafezoneBSide, one at each end of the crossing). The
-- teleport puts the character inside the one on the far side of where it stands.

local lastTeleportAt = -10

---@param message string
local function teleportNotify(message)
	if uiWindow then uiWindow:Notify({ Title = "Teleport", Text = message, Duration = 4 }) end
end

-- The safe-zone box on the far side of the field from the given position, or nil when the map has none.
---@param position Vector3
---@return BasePart?
local function farSafeZone(position)
	local chicken = replicatedStorage:FindFirstChild("ChickenOrHero")
	local gameFolder = chicken and chicken:FindFirstChild("Game")
	local session = gameFolder and gameFolder:FindFirstChild("Session")
	local mapId = session and session:GetAttribute("ActiveMapId")
	local map = mapId and workspace:FindFirstChild(mapId)
	local field = map and map:FindFirstChild("Field")
	local sideA = field and field:FindFirstChild("SafezoneASide")
	local sideB = field and field:FindFirstChild("SafezoneBSide")
	if not (sideA and sideB and sideA:IsA("BasePart") and sideB:IsA("BasePart")) then return nil end

	local toA = flat(position - sideA.Position).Magnitude
	local toB = flat(position - sideB.Position).Magnitude
	return toA > toB and sideA or sideB
end

-- Moves the character into the safe zone on the other side of the field.
local function teleportAcross()
	if os.clock() - lastTeleportAt < 1 then return end

	local character = localPlayer.Character
	local root = character and character:FindFirstChild("HumanoidRootPart")
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	if not (root and humanoid) or humanoid.Health <= 0 then return teleportNotify("No character to move") end

	-- A runner in a match counts from the countdown on (waiting at the start line), not only once the round is running.
	local inRound = localPlayer:GetAttribute("InMatch") == true and localPlayer:GetAttribute("GameRole") == "Runner"
	if flag("teleportRoundOnly") and not inRound then
		return teleportNotify("Only works as a runner in a match, including the countdown (turn off the round-only switch to override)")
	end

	local zone = farSafeZone(root.Position)
	if not zone then return teleportNotify("No safe zone found on this map") end

	-- Land inside the box at floor level, keeping the current spot along the field's width.
	local halfWidth = zone.Size.X / 2 - 4
	local x = math.clamp(root.Position.X, zone.Position.X - halfWidth, zone.Position.X + halfWidth)
	local clearance = humanoid.HipHeight + root.Size.Y / 2
	if humanoid.RigType == Enum.HumanoidRigType.R6 then
		local leg = character:FindFirstChild("Left Leg") or character:FindFirstChild("Right Leg")
		if leg and leg:IsA("BasePart") then clearance += leg.Size.Y end
	end
	local groundParams = RaycastParams.new()
	groundParams.FilterType = Enum.RaycastFilterType.Exclude
	groundParams.FilterDescendantsInstances = { character, zone }
	groundParams.RespectCanCollide = true
	groundParams.CollisionGroup = root.CollisionGroup
	local origin = Vector3.new(x, zone.Position.Y - zone.Size.Y / 2 + math.max(clearance + 4, 8), zone.Position.Z)
	local ground = workspace:Raycast(origin, Vector3.new(0, -512, 0), groundParams)
	if not ground then return teleportNotify("Ground not found at the destination; try again when the map has loaded") end
	local landing = Vector3.new(x, ground.Position.Y + clearance, zone.Position.Z)

	lastTeleportAt = os.clock()
	character:PivotTo(character:GetPivot() + (landing - root.Position))
	root.AssemblyLinearVelocity = Vector3.zero
	log("teleport to", landing)

	-- The server decides where we really are: if it moved us back, say so instead of pretending it worked.
	task.delay(1.2, function()
		local current = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
		if current and flat(current.Position - landing).Magnitude > 25 then
			teleportNotify("The server moved you back, the teleport was rejected")
		end
	end)
end

local function buildUi()
	ui = loadLibrary()
	local window = ui:CreateWindow({
		Title = "Huss Valley",
		Subtitle = "SESSION CONTROL",
		Intro = true,
		Widgets = false,
		ToggleKey = Enum.KeyCode.RightShift,
		-- Pressing "Unload Script" in Settings unloads the whole script, not just the window.
		OnDestroy = function()
			if not detaching then HussValley.detach() end
		end,
	})
	uiWindow = window

	-- A hub overlay should not blur the game while you play; Settings can turn it back on.
	ui.Flags.ui_blur.Set(false)

	-- Overview ----------------------------------------------------------------------------------------------------
	local overview = window:CreateTab("Overview", "layout-dashboard", "Your hub at a glance")
	overview:AddStatRow({
		{ Title = "Role", Get = roleCard },
		{ Title = "Auto Dodge", Get = function()
			local on = flag("autoDodge") or flag("immortal")
			return on and (flag("immortal") and "IMMORTAL" or "ON") or "OFF", on and 1 or 0.04, flag("proximity") and "proximity on" or ""
		end },
		{ Title = "This server", Get = function()
			local status = STATUS[servers.localKey]
			return status.label, servers.localKey == "unknown" and 0.04 or 1, servers.localText
		end },
	})
	overview:AddSection("Keybinds")
	overview:AddLabel("Every toggle has a key chip on its row: click it, press a key. Esc or Backspace clears it. The keybind list (Insert) shows what is on, even with the menu closed.")
	overview:AddSection("Panic")
	overview:AddButton({ Text = "Turn every feature off", Callback = function()
		for name, entry in ui.Flags do
			if entry.Type == "Toggle" and string.sub(name, 1, 3) ~= "ui_" and entry.Value then entry.Set(false) end
		end
		window:Notify({ Title = "Panic", Text = "All features disabled" })
	end })

	-- Survival ----------------------------------------------------------------------------------------------------
	window:CreateCategory("Survival")
	local combat = window:CreateTab("Combat", "swords", "Auto dodge and immortal")
	combat:AddSection("Auto Dodge")
	combat:AddToggle({ Text = "Auto Dodge", Default = false, Flag = "autoDodge" })
	combat:AddKeybind({ Text = "Auto Dodge on/off key", Default = Enum.KeyCode.G, Flag = "autoDodgeKey", Pressed = function()
		local entry = ui.Flags.autoDodge
		if entry then entry.Set(not entry.Value) end
	end })
	combat:AddToggle({ Text = "Early dodge", Description = "React to tracking catchers (dodge before the swing starts)", Default = false, Flag = "early" })
	combat:AddSlider({ Text = "Danger margin (studs)", Min = 0, Max = 4, Default = 0, Increment = 0.5, Flag = "margin" })
	combat:AddSlider({ Text = "Auto Dodge range (studs)", Min = 8, Max = 80, Default = 45, Increment = 1, Flag = "dodgeRange" })
	combat:AddToggle({ Text = "Auto Ability", Description = "Auto Ability (Q): runners when the dash is spent, catchers when a runner is close", Default = false, Flag = "autoAbility" })
	combat:AddToggle({ Text = "Haunt protection", Description = "Dodge zombies and skeleton heads (the Haunt event monsters)", Default = true, Flag = "hauntDodge", NoList = true })
	combat:AddToggle({ Text = "Stationary swing protection", Description = "Dodge swings from catchers that stand still, even when they are hitting other players", Default = true, Flag = "standingSwing", NoList = true })
	combat:AddToggle({ Text = "Proximity dodge", Description = "Proximity dodge (dash away from any catcher that gets close)", Default = false, Flag = "proximity" })
	combat:AddSlider({ Text = "Proximity range (studs)", Min = 4, Max = 14, Default = 8, Increment = 1, Flag = "proximityRange" })
	combat:AddSection("Immortal", "Protection and advanced dodge options in one place.")
	combat:AddToggle({ Text = "Immortal", Description = "Immortal (best effort): dodge every attack it can see, from any side", Default = false, Flag = "immortal", Callback = function(on) movement.immortal = on end })
	combat:AddLabel("Immortal dashes out of every attack near you, even two at once. Catches are decided by the server, so this cannot be true god mode, and a very high ping can still be too slow. Each part below is its own switch, so you can use Immortal with any mix of them.")
	combat:AddSlider({ Text = "Immortal range (studs)", Min = 8, Max = 80, Default = 45, Increment = 1, Flag = "immortalRange" })
	combat:AddDisclosure("Advanced protection settings")
