	combat:AddToggle({ Text = "Fast dash", Description = "Immortal: fastest dash the server accepts (about 0.04 s)", Default = true, Flag = "immortalFastDash", NoList = true, Callback = function(on) movement.immortalFastDash = on end })
	combat:AddToggle({ Text = "Dash in any direction", Description = "Immortal: dash in any direction, even straight ahead", Default = true, Flag = "immortalFreeDash", NoList = true, Callback = function(on) movement.immortalFreeDash = on end })
	combat:AddToggle({ Text = "Use abilities", Description = "Immortal: also use abilities (Q)", Default = true, Flag = "immortalAbility", NoList = true, Callback = function(on) movement.immortalAbility = on end })
	combat:AddToggle({ Text = "Predict moving catchers", Description = "Immortal: lead running catchers (predict where the swing starts)", Default = true, Flag = "immortalPredict", NoList = true, Callback = function(on) movement.immortalPredict = on end })
	combat:AddToggle({ Text = "Adapt to catcher speed", Description = "Immortal: wider danger zone for fast catchers", Default = true, Flag = "immortalSpeedMargin", NoList = true, Callback = function(on) movement.immortalSpeedMargin = on end })
	combat:AddToggle({ Text = "Prefer safer landings", Description = "Immortal: prefer landing spots far from every catcher", Default = true, Flag = "immortalBias", NoList = true, Callback = function(on) movement.immortalBias = on end })

